CREATE TABLE IF NOT EXISTS `quality_stats` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `period_type` VARCHAR(191) NOT NULL,
  `period_key` VARCHAR(191) NOT NULL,
  `reading_prompt_version` VARCHAR(191),
  `eval_prompt_version` VARCHAR(191),
  `variant_id` VARCHAR(191),
  `provider` LONGTEXT,
  `spread_key` VARCHAR(191),
  `reading_count` BIGINT NOT NULL DEFAULT 0,
  `eval_count` BIGINT NOT NULL DEFAULT 0,
  `heuristic_count` BIGINT NOT NULL DEFAULT 0,
  `error_count` BIGINT NOT NULL DEFAULT 0,
  `avg_overall` DOUBLE,
  `avg_personalization` DOUBLE,
  `avg_tarot_coherence` DOUBLE,
  `avg_tone` DOUBLE,
  `avg_safety` DOUBLE,
  `safety_flag_count` BIGINT DEFAULT 0,
  `low_tone_count` BIGINT DEFAULT 0,
  `low_safety_count` BIGINT DEFAULT 0,
  `avg_card_coverage` DOUBLE,
  `hallucination_count` BIGINT DEFAULT 0,
  `baseline_overall` DOUBLE,
  `delta_overall` DOUBLE,
  `created_at` DATETIME DEFAULT (UTC_TIMESTAMP()),
  `eval_model` LONGTEXT,
  `eval_source` LONGTEXT,
  PRIMARY KEY (`id`),
  `tableu_dimensions_hash` CHAR(64) CHARACTER SET ascii GENERATED ALWAYS AS (CASE WHEN eval_model IS NOT NULL AND eval_source IS NOT NULL THEN SHA2(CAST(JSON_ARRAY(COALESCE(`period_type`, ''), COALESCE(`period_key`, ''), COALESCE(`reading_prompt_version`, ''), COALESCE(`eval_prompt_version`, ''), COALESCE(`variant_id`, ''), COALESCE(`provider`, ''), COALESCE(`spread_key`, ''), COALESCE(`eval_model`, ''), COALESCE(`eval_source`, '')) AS CHAR), 256) ELSE NULL END) STORED,
  KEY `idx_quality_stats_created` (`created_at`),
  KEY `idx_quality_stats_spread` (`spread_key`),
  KEY `idx_quality_stats_variant` (`variant_id`),
  KEY `idx_quality_stats_version` (`reading_prompt_version`, `eval_prompt_version`),
  KEY `idx_quality_stats_period` (`period_type`, `period_key`),
  UNIQUE KEY `idx_quality_stats_dimensions_unique` (`tableu_dimensions_hash`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

