  `spread_key` VARCHAR(191) NOT NULL,
  `spread_name` LONGTEXT NOT NULL,
  `card_count` BIGINT NOT NULL,
  `has_reversals` BIGINT NOT NULL DEFAULT 0,
  `reversal_count` BIGINT NOT NULL DEFAULT 0,
  `question_length` BIGINT,
  `provider` VARCHAR(191),
  `reading_length` BIGINT,
  `session_seed` LONGTEXT,
  `has_reflections` BIGINT DEFAULT 0,
  `user_agent` LONGTEXT,
  `locale` LONGTEXT,
  `version` BIGINT DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_readings_provider` (`provider`),
  KEY `idx_readings_spread_key` (`spread_key`),
  KEY `idx_readings_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `sessions` (
  `id` VARCHAR(191) NOT NULL,
  `user_id` VARCHAR(191) NOT NULL,
  `created_at` BIGINT NOT NULL,
  `expires_at` BIGINT NOT NULL,
  `last_used_at` BIGINT NOT NULL,
  `user_agent` LONGTEXT,
  `ip_address` LONGTEXT,
  PRIMARY KEY (`id`),
  KEY `idx_sessions_expires_at` (`expires_at`),
  KEY `idx_sessions_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `share_note_reports` (
  `id` VARCHAR(191) NOT NULL,
  `note_id` VARCHAR(191) NOT NULL,
  `token` VARCHAR(191) NOT NULL,
  `reporter_id` VARCHAR(191) NOT NULL,
  `reason` LONGTEXT NOT NULL,
  `details` LONGTEXT,
  `user_agent` LONGTEXT,
  `created_at` BIGINT NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_share_note_reports_note_reporter` (`note_id`, `reporter_id`),
  KEY `idx_share_note_reports_token` (`token`, `created_at`),
  KEY `idx_share_note_reports_note` (`note_id`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `share_notes` (
  `id` VARCHAR(191) NOT NULL,
  `token` VARCHAR(191) NOT NULL,
  `author_name` LONGTEXT,
  `body` LONGTEXT NOT NULL,
  `card_position` LONGTEXT,
  `created_at` BIGINT NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_share_notes_token` (`token`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `share_token_entries` (
  `token` VARCHAR(191) NOT NULL,
  `entry_id` VARCHAR(191) NOT NULL,
  `sort_index` BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`token`, `entry_id`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `share_tokens` (
  `token` VARCHAR(191) NOT NULL,
  `user_id` VARCHAR(191) NOT NULL,
  `scope` LONGTEXT NOT NULL,
  `title` LONGTEXT,
  `created_at` BIGINT NOT NULL,
  `expires_at` BIGINT,
  `view_count` BIGINT NOT NULL DEFAULT 0,
  `meta_json` LONGTEXT,
  PRIMARY KEY (`token`),
  CHECK (scope IN ('entry', 'journal')),
  KEY `idx_share_tokens_user` (`user_id`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `usage_tracking` (
  `user_id` VARCHAR(191) NOT NULL,
  `month` VARCHAR(191) NOT NULL,
  `readings_count` BIGINT DEFAULT 0,
  `tts_count` BIGINT DEFAULT 0,
  `api_calls_count` BIGINT DEFAULT 0,
  `created_at` BIGINT NOT NULL,
  `updated_at` BIGINT NOT NULL,
  PRIMARY KEY (`user_id`, `month`),
  KEY `idx_usage_tracking_month` (`month`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `user_analytics_prefs` (
  `user_id` VARCHAR(191) NOT NULL,
  `archetype_journey_enabled` BIGINT DEFAULT 1,
  `show_badges` BIGINT DEFAULT 1,
  `updated_at` BIGINT NOT NULL,
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `user_media` (
  `id` VARCHAR(191) NOT NULL,
  `user_id` VARCHAR(191) NOT NULL,
  `created_at` BIGINT NOT NULL,
  `updated_at` BIGINT NOT NULL,
  `media_type` VARCHAR(191) NOT NULL,
  `source` LONGTEXT NOT NULL,
  `title` LONGTEXT,
  `prompt_question` LONGTEXT,
  `card_name` LONGTEXT,
  `position_label` LONGTEXT,
  `style_id` LONGTEXT,
  `format_id` LONGTEXT,
  `mime_type` LONGTEXT NOT NULL,
  `storage_provider` LONGTEXT NOT NULL DEFAULT ('r2'),
  `storage_key` VARCHAR(191) NOT NULL,
  `bytes` BIGINT,
  `metadata_json` LONGTEXT,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_user_media_user_storage` (`user_id`, `storage_key`),
  KEY `idx_user_media_user_type_created` (`user_id`, `media_type`, `created_at`),
  KEY `idx_user_media_user_created` (`user_id`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `user_memories` (
  `id` VARCHAR(191) NOT NULL,
  `user_id` VARCHAR(191) NOT NULL,
  `text` VARCHAR(255) NOT NULL,
  `keywords` LONGTEXT,
  `category` VARCHAR(191) DEFAULT 'general',
  `scope` VARCHAR(191) DEFAULT 'global',
  `session_id` VARCHAR(191),
  `source` LONGTEXT DEFAULT ('ai'),
  `confidence` DOUBLE DEFAULT 1.0,
  `created_at` BIGINT NOT NULL,
  `last_accessed_at` BIGINT,
  `expires_at` BIGINT,
  PRIMARY KEY (`id`),
  `tableu_idx_memories_user_text_dedup_text` VARCHAR(255) GENERATED ALWAYS AS (CASE WHEN scope = 'global' THEN `text` ELSE NULL END) STORED,
  UNIQUE KEY `idx_memories_user_text_dedup` (`user_id`, `tableu_idx_memories_user_text_dedup_text`),
  KEY `idx_memories_category` (`user_id`, `category`),
  KEY `idx_memories_session` (`session_id`),
  KEY `idx_memories_user_scope` (`user_id`, `scope`),
  KEY `idx_memories_user_recent` (`user_id`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `user_tokens` (
  `id` VARCHAR(191) NOT NULL,
  `user_id` VARCHAR(191) NOT NULL,
  `token_hash` VARCHAR(191) NOT NULL,
  `type` VARCHAR(191) NOT NULL,
  `created_at` BIGINT NOT NULL,
  `expires_at` BIGINT NOT NULL,
  `used_at` BIGINT,
  `metadata` LONGTEXT,
  `ip_address` LONGTEXT,
  `user_agent` LONGTEXT,
  PRIMARY KEY (`id`),
  CHECK (type IN ('email_verification', 'password_reset')),
  KEY `idx_user_tokens_expires_at` (`expires_at`),
  KEY `idx_user_tokens_user_type` (`user_id`, `type`),
  UNIQUE KEY `idx_user_tokens_hash` (`token_hash`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `users` (
  `id` VARCHAR(191) NOT NULL,
  `email` VARCHAR(254) NOT NULL,
  `username` VARCHAR(191) NOT NULL,
  `password_hash` LONGTEXT NOT NULL,
  `password_salt` LONGTEXT NOT NULL,
  `created_at` BIGINT NOT NULL,
  `updated_at` BIGINT NOT NULL,
  `last_login_at` BIGINT,
  `is_active` BIGINT NOT NULL DEFAULT 1,
  `email_verified` BIGINT DEFAULT 0,
  `subscription_tier` LONGTEXT DEFAULT ('free'),
  `subscription_provider` LONGTEXT,
  `subscription_status` LONGTEXT,
  `stripe_customer_id` VARCHAR(191),
  `display_name` LONGTEXT,
  `reading_tone` LONGTEXT DEFAULT ('balanced'),
  `spiritual_frame` LONGTEXT DEFAULT ('mixed'),
  `preferred_spread_depth` LONGTEXT DEFAULT ('standard'),
  `auth_provider` VARCHAR(191),
  `auth_subject` VARCHAR(191),
  `full_name` LONGTEXT,
  `avatar_url` LONGTEXT,
  PRIMARY KEY (`id`),
  KEY `idx_users_auth_provider_subject` (`auth_provider`, `auth_subject`),
  UNIQUE KEY `idx_users_stripe_customer_id` (`stripe_customer_id`),
  KEY `idx_users_username` (`username`),
  KEY `idx_users_email` (`email`),
  UNIQUE KEY `users_unique_4` (`username`),
  UNIQUE KEY `users_unique_5` (`email`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `visual_guest_principals` (
  `token_hash` VARCHAR(191) NOT NULL,
  `principal_id` VARCHAR(191) NOT NULL,
  `aggregate_scope` LONGTEXT NOT NULL,
  `expires_at` BIGINT NOT NULL,
  PRIMARY KEY (`token_hash`),
  UNIQUE KEY `visual_guest_principals_unique_0` (`principal_id`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `visual_initial_admissions` (
  `reading_result_id` VARCHAR(191) NOT NULL,
  `user_id` VARCHAR(191),
  `aggregate_scope` LONGTEXT NOT NULL,
  `binding_json` LONGTEXT NOT NULL,
  `token_hash` LONGTEXT NOT NULL,
  `expires_at` BIGINT NOT NULL,
  `created_at` BIGINT NOT NULL,
  PRIMARY KEY (`reading_result_id`),
  KEY `idx_visual_initial_admissions_owner` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `visual_initial_reservations` (
  `dispatch_id` VARCHAR(191) NOT NULL,
  `reading_result_id` LONGTEXT,
  `aggregate_scope` VARCHAR(191) NOT NULL,
  `reserved_cost_microusd` BIGINT NOT NULL,
  `reserved_at` BIGINT NOT NULL,
  PRIMARY KEY (`dispatch_id`),
  CHECK (reserved_cost_microusd > 0),
  KEY `idx_visual_initial_reservations_scope` (`aggregate_scope`, `reserved_at`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `visual_owner_revocations` (
  `user_id` VARCHAR(191) NOT NULL,
  `revoked_at` BIGINT NOT NULL,
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `visual_result_revocations` (
  `reading_result_id` VARCHAR(191) NOT NULL,
  `user_id` LONGTEXT,
  `revoked_at` BIGINT NOT NULL,
  PRIMARY KEY (`reading_result_id`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS `visual_retry_claims` (
  `id` VARCHAR(191) NOT NULL,
  `admission_scope` VARCHAR(191) NOT NULL,
  `source_fingerprint` VARCHAR(191) NOT NULL,
  `user_id` VARCHAR(191),
  `journal_entry_id` VARCHAR(191),
  `reading_result_id` LONGTEXT,
  `attempt_id` LONGTEXT,
  `visual_job_id` LONGTEXT,
  `state_version` BIGINT NOT NULL DEFAULT 1,
  `dispatch_status` LONGTEXT NOT NULL DEFAULT ('prepared'),
  `retry_status` LONGTEXT NOT NULL DEFAULT ('unavailable'),
  `created_at` BIGINT NOT NULL,
  `updated_at` BIGINT NOT NULL,
  `aggregate_scope` VARCHAR(191),
  `source_json` LONGTEXT,
  `saved_fields_json` LONGTEXT,
  `journal_state_version` BIGINT,
  `binding_json` LONGTEXT,
  `visual_token` LONGTEXT,
  `expires_at` BIGINT,
  `reserved_at` BIGINT,
  PRIMARY KEY (`id`),
  CHECK (state_version >= 1),
  CHECK (dispatch_status IN ('prepared', 'reserved', 'settled', 'revoked')),
  CHECK (retry_status IN ('available', 'pending', 'complete', 'exhausted', 'unavailable', 'revoked')),
  KEY `idx_visual_retry_claims_admission` (`aggregate_scope`, `reserved_at`),
  KEY `idx_visual_retry_claims_owner` (`user_id`),
  UNIQUE KEY `visual_retry_claims_unique_2` (`admission_scope`, `source_fingerprint`)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS _request_rate_limits (bucket_key VARCHAR(255) NOT NULL PRIMARY KEY, request_count BIGINT NOT NULL, expires_at_ms BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE IF NOT EXISTS tableu_quota_locks (identity_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY) ENGINE=InnoDB;

